(function(){
'use strict';
const KEY='nawaf-hq-v5';
const COMMANDS=[
 {id:'research',icon:'⌕',label:'بحث عميق',hint:'ابحث واجمع أفضل نتيجة موثقة',prefix:'ابحث بعمق ونفّذ هذه المهمة: '},
 {id:'analyze',icon:'◫',label:'تحليل',hint:'حلل الوضع واستخرج قرارًا عمليًا',prefix:'حلل بعمق وقدم نتيجة عملية لهذه المهمة: '},
 {id:'plan',icon:'◇',label:'خطة تنفيذ',hint:'حوّل الفكرة إلى خطوات قابلة للتطبيق',prefix:'أنشئ خطة تنفيذ مفصلة وقابلة للتطبيق لهذه المهمة: '},
 {id:'review',icon:'✓',label:'مراجعة جودة',hint:'راجع واكتشف الأخطاء والتحسينات',prefix:'نفّذ مراجعة جودة دقيقة لهذه المهمة: '},
 {id:'ideas',icon:'✦',label:'ابتكار أفكار',hint:'اقترح أفكارًا قوية وغير مكررة',prefix:'ابتكر أفضل أفكار عملية لهذه المهمة: '},
 {id:'solve',icon:'⚙',label:'حل مشكلة',hint:'شخّص السبب واقترح الحل الأفضل',prefix:'شخّص المشكلة ثم قدم الحل الأفضل والأكثر عملية: '},
 {id:'compare',icon:'⇄',label:'مقارنة',hint:'قارن الخيارات وحدد الأفضل ولماذا',prefix:'قارن الخيارات بوضوح وحدد الأفضل لهذه المهمة: '},
 {id:'report',icon:'▤',label:'إعداد تقرير',hint:'أنتج تقريرًا مختصرًا قابلًا للاعتماد',prefix:'أنتج تقريرًا تنفيذيًا واضحًا وقابلًا للاعتماد عن: '},
 {id:'custom',icon:'＋',label:'أمر مخصص',hint:'اكتب أي مهمة تريد من الموظف تنفيذها',prefix:''}
];
function read(){try{return JSON.parse(localStorage.getItem(KEY)||'{}')||{}}catch{return {}}}
function write(s,reason){localStorage.setItem(KEY,JSON.stringify(s));window.dispatchEvent(new CustomEvent('nawaf:state-updated',{detail:{reason:reason||'v6-command'}}));window.dispatchEvent(new CustomEvent('nawaf:activity-updated'))}
function uid(p){return p+Date.now().toString(36)+Math.random().toString(36).slice(2,6)}
function esc(s=''){return String(s).replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]))}
function activity(s,text){s.activity=Array.isArray(s.activity)?s.activity:[];s.activity.unshift({id:uid('a'),text,type:'REAL',at:new Date().toISOString()});s.activity=s.activity.slice(0,120)}
function ensureModal(){let root=document.getElementById('v6-command-modal');if(root)return root;root=document.createElement('div');root.id='v6-command-modal';root.className='v6-modal';root.innerHTML='<div class="v6-modal-card" role="dialog" aria-modal="true"><button class="v6-modal-close" type="button" aria-label="إغلاق">×</button><div id="v6-modal-body"></div></div>';document.body.appendChild(root);root.addEventListener('click',e=>{if(e.target===root||e.target.closest('.v6-modal-close'))close()});return root}
function open(html){const r=ensureModal();r.querySelector('#v6-modal-body').innerHTML=html;r.classList.add('show');document.body.classList.add('v6-modal-open')}
function close(){const r=document.getElementById('v6-command-modal');if(r)r.classList.remove('show');document.body.classList.remove('v6-modal-open')}
function statusAr(v){return({READY:'جاهز',IDLE:'متاح',WORKING:'يعمل الآن',RESEARCHING:'يبحث الآن',REVIEWING:'يراجع',WAITING_FOR_NAWAF:'بانتظارك',COMPLETED:'مكتمل'})[v]||v||'جاهز'}
function employeePanel(id){const s=read(),e=(s.employees||[]).find(x=>x.id===id);if(!e)return;const projects=s.projects||[];open(`<div class="v6-employee-head"><div class="v6-employee-avatar">${esc((e.name||'AI').slice(0,1))}</div><div><span class="v6-kicker">AI EMPLOYEE</span><h2>${esc(e.name)}</h2><p>${esc(e.role||e.department||'موظف AI')}</p></div><span class="v6-status ${['WORKING','RESEARCHING','REVIEWING'].includes(e.status)?'busy':''}">${statusAr(e.status)}</span></div><div class="v6-section-title"><b>وش تبي ${esc(e.name)} يسوي؟</b><span>اختر أمر، ثم اكتب المهمة.</span></div><div class="v6-command-grid">${COMMANDS.map(c=>`<button type="button" class="v6-command" data-v6-command="${c.id}"><i>${c.icon}</i><b>${c.label}</b><small>${c.hint}</small></button>`).join('')}</div><div class="v6-command-form" id="v6-command-form"><label>المشروع<select id="v6-project"><option value="">الشركة / بدون مشروع</option>${projects.map(p=>`<option value="${esc(p.id)}">${esc(p.name)}</option>`).join('')}</select></label><label>تفاصيل المهمة<textarea id="v6-details" rows="5" placeholder="مثال: راجع مشروع قدّها وحدد لي أهم 5 مشاكل تمنع الألعاب من العمل بشكل مستقر..."></textarea></label><div class="v6-run-row"><div id="v6-selected-command">اختر نوع الأمر أولًا</div><button type="button" class="v6-run" id="v6-run" disabled>▶ ابدأ التنفيذ</button></div></div><div class="v6-employee-actions"><button type="button" data-v6-edit="${esc(e.id)}">تعديل الموظف</button><button type="button" data-v6-view-tasks="${esc(e.id)}">عرض مهامه</button></div>`);let selected=null;document.querySelectorAll('[data-v6-command]').forEach(b=>b.onclick=()=>{selected=COMMANDS.find(c=>c.id===b.dataset.v6Command);document.querySelectorAll('[data-v6-command]').forEach(x=>x.classList.toggle('active',x===b));document.getElementById('v6-selected-command').innerHTML=`<b>${selected.icon} ${selected.label}</b><small>${selected.hint}</small>`;document.getElementById('v6-run').disabled=false;document.getElementById('v6-details').focus()});document.getElementById('v6-run').onclick=()=>runCommand(e.id,selected,document.getElementById('v6-project').value,document.getElementById('v6-details').value)}
async function runCommand(employeeId,command,projectId,details){if(!command)return;details=String(details||'').trim();if(!details){document.getElementById('v6-details')?.focus();return}const s=read(),e=(s.employees||[]).find(x=>x.id===employeeId);if(!e)return;const title=(command.label==='أمر مخصص'?'مهمة':command.label)+': '+details.slice(0,80);const task={id:uid('t'),title,details:command.prefix+details,projectId:projectId||'',employeeId:e.id,status:'READY',progress:0,createdAt:new Date().toISOString(),kind:command.id.toUpperCase(),createdBy:'NAWAF'};s.tasks=Array.isArray(s.tasks)?s.tasks:[];s.tasks.unshift(task);e.status='READY';e.task=title;activity(s,`تم تكليف ${e.name}: ${title}`);write(s,'employee-command');close();toast(`تم إرسال المهمة إلى ${e.name} وبدأ التنفيذ`);setTimeout(async()=>{try{if(window.NawafAgents?.runTask)await window.NawafAgents.runTask(task.id);else if(window.NawafAgents?.runNext)await window.NawafAgents.runNext()}catch(err){toast('تم حفظ المهمة، لكن محرك التنفيذ يحتاج إعادة المحاولة')}} ,180)}
function employeeCreator(){const s=read(),projects=s.projects||[];open(`<div class="v6-creator-head"><span class="v6-kicker">NEW AI EMPLOYEE</span><h2>إضافة موظف AI</h2><p>حدّد دوره بوضوح، وبعدها يصير جاهز لاستقبال الأوامر مباشرة.</p></div><div class="v6-create-grid"><label>الاسم<input id="v6-new-name" placeholder="مثال: خالد"></label><label>المسمى الوظيفي<input id="v6-new-role" placeholder="مثال: مهندس برمجيات AI"></label><label>القسم<select id="v6-new-dept"><option>التقنية والبحث</option><option>المنتج والتجربة</option><option>الجودة والمراجعة</option><option>التحليلات</option><option>البحث</option><option>العمليات</option><option>الإدارة العامة</option><option>الأنظمة والبنية</option></select></label><label>المشروع الأساسي<select id="v6-new-project"><option value="">بدون مشروع ثابت</option>${projects.map(p=>`<option value="${esc(p.id)}">${esc(p.name)}</option>`).join('')}</select></label><label class="wide">مسؤوليته الأساسية<textarea id="v6-new-mission" rows="4" placeholder="مثال: مسؤول عن إصلاح الأخطاء التقنية، مراجعة الكود، واقتراح التحسينات بدون كسر المميزات العاملة."></textarea></label></div><button type="button" class="v6-run full" id="v6-create-employee">＋ أضف الموظف وخله جاهز</button>`);document.getElementById('v6-create-employee').onclick=()=>{const name=document.getElementById('v6-new-name').value.trim(),role=document.getElementById('v6-new-role').value.trim(),department=document.getElementById('v6-new-dept').value,projectId=document.getElementById('v6-new-project').value,mission=document.getElementById('v6-new-mission').value.trim();if(!name||!role){toast('اكتب اسم الموظف ومسمّاه الوظيفي');return}const q=read();q.employees=Array.isArray(q.employees)?q.employees:[];const e={id:uid('emp'),name,role,department,status:'READY',task:'',productivity:100,mission,projectId,createdAt:new Date().toISOString()};q.employees.push(e);activity(q,`تمت إضافة موظف AI جديد: ${name} — ${role}`);write(q,'employee-created');close();toast(`${name} انضاف وصار جاهز للأوامر`);setTimeout(()=>employeePanel(e.id),250)}}
function toast(text){let t=document.querySelector('.v6-toast');if(!t){t=document.createElement('div');t.className='v6-toast';document.body.appendChild(t)}t.textContent=text;t.classList.add('show');clearTimeout(toast.t);toast.t=setTimeout(()=>t.classList.remove('show'),2600)}
function commandDeck(){const host=document.querySelector('.hq-3d-stage');if(!host||host.dataset.v6Deck==='1')return;host.dataset.v6Deck='1';host.innerHTML='<div class="v6-command-deck" id="v6-command-deck"></div>';renderDeck()}
function renderDeck(){const deck=document.getElementById('v6-command-deck');if(!deck)return;const s=read(),employees=(s.employees||[]).slice(0,10),active=(s.tasks||[]).filter(t=>['WORKING','RESEARCHING','REVIEWING'].includes(t.status)).length,waiting=(s.tasks||[]).filter(t=>t.status==='WAITING_FOR_NAWAF').length;deck.innerHTML=`<div class="v6-deck-head"><div><span class="v6-kicker">AI WORKFORCE COMMAND CENTER</span><h2>فريقك جاهز للتنفيذ</h2><p>اضغط على أي موظف وأعطه أمر مباشر.</p></div><div class="v6-live-summary"><span><i></i>${active} يعمل الآن</span><span>${waiting} بانتظارك</span></div></div><div class="v6-staff-grid">${employees.map(e=>`<button type="button" class="v6-staff-card" data-employee="${esc(e.id)}"><div class="v6-staff-top"><span class="v6-staff-avatar">${esc((e.name||'AI').slice(0,1))}</span><i class="v6-dot ${['WORKING','RESEARCHING','REVIEWING'].includes(e.status)?'busy':''}"></i></div><b>${esc(e.name)}</b><small>${esc(e.role||e.department||'موظف AI')}</small><div class="v6-card-foot"><span>${statusAr(e.status)}</span><strong>أعطه أمر ←</strong></div></button>`).join('')}<button type="button" class="v6-staff-card add" id="v6-add-card"><span>＋</span><b>موظف جديد</b><small>أنشئ تخصصًا جديدًا للفريق</small></button></div>`;document.getElementById('v6-add-card').onclick=employeeCreator}
function iconSvg(name){const p={dashboard:'M3 12l9-8 9 8v8a2 2 0 0 1-2 2h-4v-6H9v6H5a2 2 0 0 1-2-2z',office:'M4 21V5a2 2 0 0 1 2-2h12a2 2 0 0 1 2 2v16M8 7h2m4 0h2M8 11h2m4 0h2M8 15h2m4 0h2M9 21v-3h6v3',workforce:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2m7-10a4 4 0 1 0 0-8 4 4 0 0 0 0 8m13 10v-2a4 4 0 0 0-3-3.87m-2-11.96a4 4 0 0 1 0 7.75',projects:'M4 4h6l2 2h8v12a2 2 0 0 1-2 2H4a2 2 0 0 1-2-2V6a2 2 0 0 1 2-2z',tasks:'M9 11l3 3L22 4M21 12v7a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h11',approvals:'M12 22a10 10 0 1 0 0-20 10 10 0 0 0 0 20zm-3-10 2 2 4-4',reports:'M6 2h9l5 5v13a2 2 0 0 1-2 2H6a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2zm8 1v5h5M8 13h8M8 17h8M8 9h2',settings:'M12 15.5A3.5 3.5 0 1 0 12 8a3.5 3.5 0 0 0 0 7.5zM19.4 15a1.7 1.7 0 0 0 .34 1.88l.06.06-2.83 2.83-.06-.06a1.7 1.7 0 0 0-1.88-.34 1.7 1.7 0 0 0-1.03 1.56V21h-4v-.08a1.7 1.7 0 0 0-1.03-1.56 1.7 1.7 0 0 0-1.88.34l-.06.06-2.83-2.83.06-.06A1.7 1.7 0 0 0 4.6 15a1.7 1.7 0 0 0-1.56-1.03H3v-4h.08A1.7 1.7 0 0 0 4.64 8.94a1.7 1.7 0 0 0-.34-1.88L4.24 7l2.83-2.83.06.06A1.7 1.7 0 0 0 9 4.57 1.7 1.7 0 0 0 10 3.01V3h4v.08a1.7 1.7 0 0 0 1.03 1.56 1.7 1.7 0 0 0 1.88-.34l.06-.06L19.8 7.07l-.06.06a1.7 1.7 0 0 0-.34 1.88A1.7 1.7 0 0 0 20.96 10H21v4h-.08A1.7 1.7 0 0 0 19.4 15z'};return `<svg viewBox="0 0 24 24" aria-hidden="true"><path d="${p[name]||p.dashboard}"/></svg>`}
function polishNav(){document.querySelectorAll('.nav [data-view],.mobile-nav [data-view]').forEach(b=>{if(b.dataset.v6Icon)return;b.dataset.v6Icon='1';const label=b.querySelector('span')?.textContent||b.textContent.trim();b.innerHTML=iconSvg(b.dataset.view)+`<span>${esc(label)}</span>`})}
function intercept(e){const emp=e.target.closest('[data-employee]');if(emp){e.preventDefault();e.stopImmediatePropagation();employeePanel(emp.dataset.employee);return}const add=e.target.closest('#new-employee');if(add){e.preventDefault();e.stopImmediatePropagation();employeeCreator();return}const edit=e.target.closest('[data-v6-edit]');if(edit){close();setTimeout(()=>employeePanel(edit.dataset.v6Edit),100);return}const vt=e.target.closest('[data-v6-view-tasks]');if(vt){close();document.querySelector('[data-view="tasks"]')?.click();return}}
document.addEventListener('click',intercept,true);
function boot(){polishNav();commandDeck()}
document.addEventListener('DOMContentLoaded',()=>setTimeout(boot,250));window.addEventListener('nawaf:state-updated',()=>setTimeout(()=>{polishNav();renderDeck()},80));setInterval(()=>{polishNav();commandDeck()},2200);
window.NawafHQV6={employeePanel,employeeCreator,renderDeck};
})();